<template><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" class="destiny-node" :class="{selected}" :style="{color}" :title="tooltip||label" :aria-label="tooltip||label" @click="$emit('select')"><AssetImage class="node-skin" :src="skin" fit="contain"/><CharacterPortraitFrame v-if="portrait" class="node-portrait" :src="portrait" :selected="selected"/><text class="node-label">{{label}}</text></button></template><script setup lang="ts">
import {activateFocused} from '../../utils/keyboard';
import {computed} from 'vue';import CharacterPortraitFrame from '../character/CharacterPortraitFrame.vue';import AssetImage from '../common/AssetImage.vue';import {uiAssets} from '../../config/ui-assets';const props=defineProps<{type:string;label:string;portrait?:string;selected?:boolean;tooltip?:string}>();defineEmits<{select:[]}>();const skins:Record<string,string>={VIDEO:uiAssets.destiny.node,PAGE:uiAssets.destiny.moon,CHOICE:uiAssets.destiny.eye,ROUTE_CLOSED:uiAssets.destiny.closed,ENDING:uiAssets.destiny.lotus,TRUE_ROUTE:uiAssets.destiny.true};const colors:Record<string,string>={VIDEO:'#72a4ff',PAGE:'#bb94ed',CHOICE:'#edb16b',ROUTE_CLOSED:'#a9abb1',ENDING:'#8bd8a3',TRUE_ROUTE:'#f4d89a'};const skin=computed(()=>skins[props.type]||uiAssets.destiny.node),color=computed(()=>colors[props.type]||'#c7ab79')</script><style scoped>.destiny-node{position:relative;width:74px;height:86px;padding:0;background:none;border:0;overflow:visible;margin:0;font-size:10px;cursor:pointer}.destiny-node:after{border:0}.node-skin{position:absolute;left:5px;top:0;width:64px;height:64px;filter:drop-shadow(0 0 5px currentColor)}.node-portrait{position:absolute;left:18px;top:13px;width:38px;height:38px;border-radius:50%}.node-label{position:absolute;top:66px;left:-10px;right:-10px;font-size:10px;line-height:1.4;color:inherit}.selected .node-skin{filter:brightness(1.5) drop-shadow(0 0 10px currentColor)}.destiny-node{transition:transform .25s;z-index:2}.destiny-node:hover,.destiny-node:focus-visible{transform:scale(1.08);z-index:5}.node-portrait{left:9px;top:4px;width:56px;height:56px;border-radius:0}.node-skin{filter:drop-shadow(0 0 2px currentColor);opacity:.8}.node-label{font-size:10px;max-width:94px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.selected .node-skin{filter:brightness(1.15) drop-shadow(0 0 4px currentColor)}</style>
